const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: 'O' },
      { kind: 'text', payload: 'P' },
      { kind: 'text', payload: 'F' }
    ];
  },
  render: function (input, metrics) {
    var rod = [['M', 80, 195], ['L', 560, 195], ['L', 560, 205], ['L', 80, 205], ['Z']];
    var pivot = [['M', 220, 206], ['L', 176, 262], ['L', 264, 262], ['Z']];
    var oDot = visualSdk.circle(320, 200, 8);
    var fShaft = [['M', 560, 196], ['L', 560, 104]];
    var fHead = [['M', 552, 122], ['L', 560, 100], ['L', 568, 122], ['Z']];
    return {
      schemaVersion: 1,
      sceneId: 'lever-source-transcription',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: input.viewport.widthDu, height: input.viewport.heightDu },
      paths: [
        { id: 'rod', commands: rod },
        { id: 'pivot', commands: pivot },
        { id: 'odot', commands: oDot },
        { id: 'fshaft', commands: fShaft },
        { id: 'fhead', commands: fHead }
      ],
      root: {
        type: 'group',
        children: [
          { type: 'path', pathId: 'rod', fill: '#5B6B82' },
          { type: 'path', pathId: 'pivot', fill: '#8A94A6' },
          { type: 'path', pathId: 'odot', fill: '#26354A' },
          { type: 'path', pathId: 'fshaft', fill: '#C0392B', stroke: { width: 3 } },
          { type: 'path', pathId: 'fhead', fill: '#C0392B' },
          { type: 'label', contentId: metrics[0].contentId, anchor: { x: 320, y: 184 }, hAlign: 'center', vAlign: 'bottom', color: '#26354A' },
          { type: 'label', contentId: metrics[1].contentId, anchor: { x: 220, y: 270 }, hAlign: 'center', vAlign: 'top', color: '#26354A' },
          { type: 'label', contentId: metrics[2].contentId, anchor: { x: 576, y: 104 }, hAlign: 'left', vAlign: 'middle', color: '#C0392B' }
        ]
      }
    };
  }
};
